var TimeLimitedCache = function() {
    // key -> { value, timer }; a key is present in the Map only while it is un-expired
    this.store = new Map();
};

/**
 * @param {number} key
 * @param {number} value
 * @param {number} duration time until expiration in ms
 * @return {boolean} if un-expired key already existed
 */
TimeLimitedCache.prototype.set = function(key, value, duration) {
    const existed = this.store.has(key);
    // Overwriting: cancel the old expiry timer so it cannot delete the new entry later
    if (existed) clearTimeout(this.store.get(key).timer);
    // Arrow function keeps `this` pointing at the cache instance
    const timer = setTimeout(() => this.store.delete(key), duration);
    this.store.set(key, { value, timer });
    return existed;
};

/**
 * @param {number} key
 * @return {number} value associated with key
 */
TimeLimitedCache.prototype.get = function(key) {
    return this.store.has(key) ? this.store.get(key).value : -1;
};

/**
 * @return {number} count of non-expired keys
 */
TimeLimitedCache.prototype.count = function() {
    return this.store.size;
};

/**
 * const timeLimitedCache = new TimeLimitedCache()
 * timeLimitedCache.set(1, 42, 1000); // false
 * timeLimitedCache.get(1) // 42
 * timeLimitedCache.count() // 1
 */
